    HeatCalc
  :root {
  --color-primary: #1a5276;
  --color-primary-light: #2e86c1;
}

html, body, #root {
  height: 100%;
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
}

.ant-typography-secondary {
  color: #595959 !important;
}

.ant-empty-description,
.ant-tag {
  color: #595959 !important;
}

.ant-tag-green {
  color: #135200 !important;
}

.ant-btn-link:not(:disabled) {
  color: #1a5276;
}

.ant-table-expanded-row-fixed {
  color: #595959 !important;
}

.cell-invalid {
  border: 2px solid #d9363e !important;
  background-color: #fff1f0;
}

/* Подсветка строки таблицы с невалидным расчётом (BR-UI-03) */
.row-invalid > td {
  background-color: #fff1f0 !important;
}
.row-invalid:hover > td {
  background-color: #ffe7e6 !important;
}

.row-dirty > td {
  background-color: #fffbe6 !important;
}

.row-dirty:hover > td {
  background-color: #fff4bf !important;
}

.row-excel-new:not(.row-dirty):not(.row-excel-dirty) > td {
  background-color: #f8fafc !important;
}

.row-excel-new:not(.row-dirty):not(.row-excel-dirty):hover > td {
  background-color: #eef6ff !important;
}

.calc-spreadsheet--excel-mode .row-excel-dirty .excel-row-header-button {
  border-left: 3px solid #d97706;
  background: #fff7d6;
  color: #7a4b00;
  font-weight: 700;
}

.calc-spreadsheet--excel-mode .row-excel-error .excel-row-header-button {
  border-left: 3px solid #d9363e;
  background: #fff1f0;
  color: #a8071a;
  font-weight: 700;
}

.object-count-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.object-count-segment {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  border: 1px solid #d9e7ef;
  border-radius: 6px;
  background: #f8fbfd;
  color: #34495e;
  font-size: 11px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.object-count-segment.success {
  border-color: #b7eb8f;
  background: #f6ffed;
  color: #135200;
}

.object-count-segment.warning {
  border-color: #ffd591;
  background: #fff7e6;
  color: #d46b08;
}

.heatcalc-header {
  background: #fff;
  color: #213244;
  height: auto;
  line-height: 1;
  padding: 0 10px;
  display: flex;
  flex-direction: column;
  gap: 0;
